    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
        import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';

        // --- 1. SETUP ---
        const scene = new THREE.Scene();

        const camera = new THREE.PerspectiveCamera(35, window.innerWidth / window.innerHeight, 0.1, 100);
        // ZOOMED OUT: Moved from (8,2,8) to (12, 5, 12)
        camera.position.set(12, 5, 12); 

        const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        renderer.toneMapping = THREE.ACESFilmicToneMapping;
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        renderer.localClippingEnabled = true; 
        document.body.appendChild(renderer.domElement);

        // HDRI Environment for realistic metal reflections
        const pmremGenerator = new THREE.PMREMGenerator(renderer);
        scene.environment = pmremGenerator.fromScene(new RoomEnvironment(), 0.04).texture;

        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;
        controls.enableZoom = false;
        controls.autoRotate = true;
        controls.autoRotateSpeed = 0.5;

        // --- 2. MATERIALS ---

        // Clipping Plane setup
        const startY = 4.0;
        const endY = -4.0;
        const clipPlane = new THREE.Plane(new THREE.Vector3(0, -1, 0), startY);

        // Clean Titanium (Shiny, slightly imperfect)
        const titaniumMat = new THREE.MeshPhysicalMaterial({
            color: 0xffffff,
            metalness: 1.0,
            roughness: 0.3,
            clearcoat: 1.0,
            clearcoatRoughness: 0.1,
            side: THREE.DoubleSide
        });

        // "Swarf" Material (Burrs)
        // These are darker, rougher, and have no clearcoat (raw cut metal)
        const swarfMat = new THREE.MeshStandardMaterial({
            color: 0x554433, // Slight brownish tint (heat tint from cutting)
            metalness: 0.8,
            roughness: 0.7,
            clippingPlanes: [clipPlane],
            side: THREE.DoubleSide,
            flatShading: true // Makes it look more jagged
        });

        // --- 3. THE PART (Bolt) ---
        const boltGroup = new THREE.Group();
        scene.add(boltGroup);

        // Hex Head Stack
        const headGroup = new THREE.Group();
        headGroup.position.y = 2.8;
        headGroup.add(new THREE.Mesh(new THREE.CylinderGeometry(1.3, 1.6, 0.2, 6), titaniumMat).translateY(0.6)); // Chamfer
        headGroup.add(new THREE.Mesh(new THREE.CylinderGeometry(1.6, 1.6, 1.0, 6), titaniumMat)); // Body
        headGroup.add(new THREE.Mesh(new THREE.CylinderGeometry(1.6, 1.6, 0.2, 32), titaniumMat).translateY(-0.6)); // Washer
        boltGroup.add(headGroup);

        // Shaft
        const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.88, 0.88, 6.5, 64), titaniumMat);
        shaft.position.y = -0.5;
        shaft.receiveShadow = true;
        boltGroup.add(shaft);

        // Spiral Threads
        class SpiralCurve extends THREE.Curve {
            getPoint(t) {
                const turns = 16;
                const angle = 2 * Math.PI * t * turns;
                const radius = 0.9;
                const height = (t * 5.5) - 2.8;
                return new THREE.Vector3(radius * Math.cos(angle), height, radius * Math.sin(angle));
            }
        }
        const threadGeo = new THREE.TubeGeometry(new SpiralCurve(), 300, 0.08, 8, false);
        const threads = new THREE.Mesh(threadGeo, titaniumMat);
        threads.castShadow = true;
        threads.receiveShadow = true;
        boltGroup.add(threads);

        // --- 4. REALISTIC "SWARF" GENERATION (The Burrs) ---
        // Generates random curly ribbons simulating metal chips

        function createRandomSwarf() {
            // Create a random chaotic path
            const points = [];
            let currentPoint = new THREE.Vector3(0,0,0);

            // Generate 5-8 segments per chip
            const segments = 5 + Math.floor(Math.random() * 4);

            for(let i=0; i<segments; i++) {
                points.push(currentPoint.clone());
                // Move in a random "curling" direction
                currentPoint.x += (Math.random() - 0.5) * 0.3;
                currentPoint.y += (Math.random() - 0.5) * 0.3;
                currentPoint.z += (Math.random() - 0.5) * 0.3;
            }

            const path = new THREE.CatmullRomCurve3(points);
            // Tube with varying radius looks like twisted metal
            const geometry = new THREE.TubeGeometry(path, 12, 0.04, 3, false);
            return new THREE.Mesh(geometry, swarfMat);
        }

        const burrCount = 60; // Fewer burrs, but more complex shapes
        for(let i=0; i<burrCount; i++) {
            const swarf = createRandomSwarf();

            // Position on the thread tips
            const angle = Math.random() * Math.PI * 2;
            const r = 0.95; 
            const y = (Math.random() * 5.5) - 3.2; 

            swarf.position.set(Math.cos(angle)*r, y, Math.sin(angle)*r);

            // Orient randomy
            swarf.rotation.set(Math.random()*Math.PI, Math.random()*Math.PI, Math.random()*Math.PI);

            // Random Scale (some big long chips, some small)
            const s = 0.8 + Math.random();
            swarf.scale.set(s, s, s);

            boltGroup.add(swarf);
        }

        // --- 5. LASER SCANNER ---
        const laserGeo = new THREE.RingGeometry(1.4, 1.45, 64);
        const laserMat = new THREE.MeshBasicMaterial({
            color: 0x00aaff,
            transparent: true,
            opacity: 0.0,
            side: THREE.DoubleSide,
            blending: THREE.AdditiveBlending
        });
        const laser = new THREE.Mesh(laserGeo, laserMat);
        laser.rotation.x = Math.PI / 2;
        laser.position.y = startY;
        scene.add(laser);

        const laserLight = new THREE.PointLight(0x00aaff, 0, 3);
        laser.add(laserLight);

        // --- 6. LIGHTING ---
        const spot1 = new THREE.SpotLight(0xffffff, 40);
        spot1.position.set(10, 20, 10);
        spot1.castShadow = true;
        scene.add(spot1);

        const spot2 = new THREE.SpotLight(0x4455ff, 15);
        spot2.position.set(-15, 0, -5);
        scene.add(spot2);

        const spot3 = new THREE.SpotLight(0xffaa77, 10);
        spot3.position.set(5, -10, 5);
        scene.add(spot3);

        // --- 7. LOGIC ---
        function updateScroll() {
            const scrollMax = document.body.scrollHeight - window.innerHeight;
            const percent = Math.min(window.scrollY / scrollMax, 1);
            const currentY = startY - (percent * (startY - endY));

            clipPlane.constant = currentY;
            laser.position.y = currentY;

            if(percent > 0.02 && percent < 0.98) {
                laserMat.opacity = 0.6;
                laserLight.intensity = 1.0;
                boltGroup.rotation.y += 0.08; 
            } else {
                laserMat.opacity = 0;
                laserLight.intensity = 0;
            }
        }

        window.addEventListener('scroll', updateScroll);
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        function animate() {
            requestAnimationFrame(animate);
            controls.update();
            renderer.render(scene, camera);
        }

        updateScroll();
        animate();

    </script>
</body>
